(function(){
var R={"station":"AeroTemp Pro \u2014 Home Rooftop, Portland","temp_c":18.4,"condition":"light rain","humidity":81};
function cToF(c){return c*9/5+32;}
console.log("Station: "+R.station);
console.log(R.temp_c+"°C / "+cToF(R.temp_c).toFixed(1)+"°F · "+R.condition+" · humidity "+R.humidity+"%");
console.log("OK: station report complete");
})();

